on conflict (id) do update set name_ko = excluded.name_ko, name_en = excluded.name_en, city_ko = excluded.city_ko, country_ko = excluded.country_ko, country_code = excluded.country_code, region = excluded.region, race_date = excluded.race_date, date_confidence = excluded.date_confidence, is_major = excluded.is_major, entry_type = excluded.entry_type, entry_opens = excluded.entry_opens, entry_closes = excluded.entry_closes, entry_confidence = excluded.entry_confidence, entry_fee = excluded.entry_fee, entry_fee_currency = excluded.entry_fee_currency, distances = excluded.distances, field_size = excluded.field_size, course = excluded.course, flight_hours = excluded.flight_hours, official_url = excluded.official_url, source_url = excluded.source_url, last_verified = excluded.last_verified, notes_ko = excluded.notes_ko;

on conflict (id) do update set name = excluded.name, url = excluded.url, note = excluded.note;

on conflict (id) do update set agency_id = excluded.agency_id, title = excluded.title, nights = excluded.nights, price_solo_krw = excluded.price_solo_krw, price_group_krw = excluded.price_group_krw, group_min = excluded.group_min, includes = excluded.includes, url = excluded.url, updated_at = excluded.updated_at;

on conflict (race_id) do update set flight_low_krw = excluded.flight_low_krw, flight_mid_krw = excluded.flight_mid_krw, flight_high_krw = excluded.flight_high_krw, hotel_night_krw = excluded.hotel_night_krw, daily_krw = excluded.daily_krw;
